// Spec 015 T015 (generated by make-plant-t015.mjs; don't edit by hand): three new comps on the
// practice project for the expression reads' live fixtures. Builds only; never saves.
//   015 Rig     Comp 1's motion rig: Shake Control with Comp 1's Position and Rotation
//               expressions, rock.png under it, Sweep Control (two Position keys), Black Solid 1
//               (eye off) with CC Light Sweep's Center reading Sweep Control, two G Shakers.
//   015 Planted the Edge Cases rows: errors (E4), off (E3), over keys (E1), wiggle (E28), joined
//               and separated with stale hidden halves (E29), guide and matte links (E15, E16),
//               index and index - 1 (E11), comp() (E13), a run-time name (E12), Source Text (E9),
//               a constant parent (E19).
//   015 Thirty  30 expressions (SC-007).
var proj = app.project;
function newComp(name, dur) { return proj.items.addComp(name, 1920, 1080, 1, dur, 30); }
function tp(l, mn) { return l.property("ADBE Transform Group").property(mn); }
function solid(c, name, w, h) { return c.layers.addSolid([0.5, 0.5, 0.5], name, w || 200, h || 200, 1); }
function nul(c, name) { var n = c.layers.addNull(); n.name = name; tp(n, "ADBE Anchor Point").setValue([0, 0]); return n; }
function expr(p, t) { p.expression = t; return p; }
var out = {};

// ---- 015 Rig (built bottom first: each add goes on top)
var rig = newComp("015 Rig", 5.005);
rig.frameRate = 29.97;
var white = solid(rig, "White Solid 1", 1920, 1080);
var rock = solid(rig, "rock.png", 1588, 535);
tp(rock, "ADBE Anchor Point").setValue([794, 267.5]);
var sweep = nul(rig, "Sweep Control");
tp(sweep, "ADBE Position").setValueAtTime(3.37, [222, 483]);
tp(sweep, "ADBE Position").setValueAtTime(3.537, [1611, 483]);
var shake = nul(rig, "Shake Control");
tp(shake, "ADBE Position").setValue([960, 540]);
expr(tp(shake, "ADBE Position"), "// Rock shake with multiple impacts (Position + shared array)\namps = [6,12,20];   // amplitude in pixels\nfreq = 8;  // shakes per second\ndecays = [1,4,10];  // how quickly it settles\n\n// Times of hammer hits (seconds)\nimpacts = [0.5, 1.5, 2.5];\n\noffset = [0,0];\n\nfor (i = 0; i < impacts.length; i++){\n  t = time - impacts[i];\n  if (t >= 0){\n\t  amp=amps[1];\n\t  decay=decays[1];\n    offset += [Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t)*amp,\n               Math.cos(freq*t*2*Math.PI)/Math.exp(decay*t)*amp];\n  }\n}\n\nvalue + offset\n");
expr(tp(shake, "ADBE Rotate Z"), "// Rock shake with multiple impacts (Rotation + shared array)\namps = [.25,.5,.75];    // amplitude in degrees\nfreq = 10;\ndecay = 3;\n\n// Same impact times as Position\nimpacts = [0.5, 1.5, 2.5];\n\nrot = 0;\n\nfor (i = 0; i < impacts.length; i++){\n  t = time - impacts[i];\n  if (t >= 0){\n\t  amp=amps[i];\n    rot += Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t)*amp;\n  }\n}\n\nvalue + rot\n");
rock.parent = shake;
tp(rock, "ADBE Position").setValue([0, 0]);
var black = solid(rig, "Black Solid 1", 1920, 1080);
var fx = black.property("ADBE Effect Parade").addProperty("CC Light Sweep");
expr(fx.property("CC Light Sweep-0001"), "thisComp.layer(\"Sweep Control\").transform.position");
black.enabled = false;
solid(rig, "G Shakers"); solid(rig, "G Shakers");
rig.time = 0.6;
out.rig = rig.id;

// ---- 015 Planted
var pc = newComp("015 Planted", 6);
var wig = solid(pc, "Wiggle");
expr(tp(wig, "ADBE Position"), "wiggle(5, 20)");
var kid = solid(pc, "Const Kid");
var cpar = nul(pc, "Const Parent");
tp(cpar, "ADBE Position").setValue([300, 300]);
expr(tp(cpar, "ADBE Position"), "value");
kid.parent = cpar;
var words = pc.layers.addText("Words");
expr(words.property("ADBE Text Properties").property("ADBE Text Document"), '"Hello " + thisLayer.name');
var runName = solid(pc, "Runtime Name");
expr(tp(runName, "ADBE Position"), 'n = "Ct" + "rl";\nthisComp.layer(n).transform.position');
var compRef = solid(pc, "Comp Ref");
expr(tp(compRef, "ADBE Opacity"), 'comp("Mentor Practice").layer("Logo").transform.opacity');
var offLink = solid(pc, "Offset Link");
expr(tp(offLink, "ADBE Rotate Z"), "thisComp.layer(index - 1).transform.rotation");
var idxLink = solid(pc, "Index Link");
expr(tp(idxLink, "ADBE Position"), "thisComp.layer(1).transform.position");
var fill = solid(pc, "Matte Fill");
var matte = solid(pc, "Matte Link");
expr(tp(matte, "ADBE Rotate Z"), 'thisComp.layer("Ctrl").transform.rotation');
fill.setTrackMatte(matte, TrackMatteType.ALPHA);
var guide = solid(pc, "Guide Link");
guide.guideLayer = true;
expr(tp(guide, "ADBE Opacity"), 'thisComp.layer("Ctrl").transform.position[0] / 10');
// Separated: Position (hidden now) keeps 500, 500; X has the expression.
var sep = solid(pc, "Separated");
tp(sep, "ADBE Position").setValue([500, 500]);
tp(sep, "ADBE Position").dimensionsSeparated = true;
tp(sep, "ADBE Position_0").setValue(800);
tp(sep, "ADBE Position_1").setValue(300);
expr(tp(sep, "ADBE Position_0"), "value + time * 10");
// Joined: X and Y (hidden now) keep 700, 650; Position has the expression.
var joined = solid(pc, "Joined");
tp(joined, "ADBE Position").dimensionsSeparated = true;
tp(joined, "ADBE Position_0").setValue(700);
tp(joined, "ADBE Position_1").setValue(650);
tp(joined, "ADBE Position").dimensionsSeparated = false;
tp(joined, "ADBE Position").setValue([520, 520]);
expr(tp(joined, "ADBE Position"), "value + [0, time * 10]");
var over = solid(pc, "Over Keys");
tp(over, "ADBE Position").setValueAtTime(0, [200, 800]);
tp(over, "ADBE Position").setValueAtTime(2, [600, 800]);
expr(tp(over, "ADBE Position"), "value + [0, 20]");
var off = solid(pc, "Off Expr");
tp(off, "ADBE Scale").setValueAtTime(0, [100, 100]);
tp(off, "ADBE Scale").setValueAtTime(2, [150, 150]);
expr(tp(off, "ADBE Scale"), "[50, 50]");
tp(off, "ADBE Scale").expressionEnabled = false;
var errFx = solid(pc, "Err Effect");
var slider = errFx.property("ADBE Effect Parade").addProperty("ADBE Slider Control");
expr(slider.property("ADBE Slider Control-0001"), 'thisComp.layer("Gone").transform.position[0]');
var errTf = solid(pc, "Err Transform");
tp(errTf, "ADBE Position").setValue([1500, 200]);
expr(tp(errTf, "ADBE Position"), 'thisComp.layer("Gone").transform.position');
var ctrl = nul(pc, "Ctrl");
tp(ctrl, "ADBE Position").setValueAtTime(0, [100, 100]);
tp(ctrl, "ADBE Position").setValueAtTime(4, [1800, 100]);
tp(ctrl, "ADBE Rotate Z").setValue(15);
pc.time = 0.6;
out.planted = pc.id;

// ---- 015 Thirty: 10 layers with 3 expressions each
var th = newComp("015 Thirty", 4);
for (var i = 1; i <= 10; i++) {
    var l = solid(th, "Row " + i);
    expr(tp(l, "ADBE Position"), "value + [Math.sin(time * " + i + ") * 20, 0]");
    expr(tp(l, "ADBE Rotate Z"), 'thisComp.layer("Thirty Ctrl").transform.rotation * ' + i);
    expr(tp(l, "ADBE Opacity"), "linear(time, 0, 4, 0, 100)");
}
var tc = nul(th, "Thirty Ctrl");
tp(tc, "ADBE Rotate Z").setValueAtTime(0, 0);
tp(tc, "ADBE Rotate Z").setValueAtTime(4, 90);
th.time = 1;
out.thirty = th.id;

var errors = {};
var probe = [[pc, "Err Transform"], [pc, "Err Effect"]];
for (var e = 0; e < probe.length; e++) {
    var L = probe[e][0].layer(probe[e][1]);
    var p = e === 0 ? tp(L, "ADBE Position") : L.property("ADBE Effect Parade").property(1).property(1);
    errors[probe[e][1]] = { enabled: p.expressionEnabled, error: p.expressionError };
}
out.errors = errors;
return out;
